function resize(){const r=scene.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
function line(a,b,color,width=2){ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.stroke()}
function circle(x,y,r,fill,stroke=null,sw=1){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=sw;ctx.stroke()}}
function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function gradient(x1,y1,x2,y2,stops){const g=ctx.createLinearGradient(x1,y1,x2,y2);stops.forEach(s=>g.addColorStop(s[0],s[1]));return g}
function draw(){if(!W||!H)return;ctx.clearRect(0,0,W,H);const compact=W<500;const scale=Math.min(W/750,H/410);const bg=gradient(0,0,0,H,[[0,'#e5e0d1'],[.58,'#d7d2c2'],[.59,'#c7c3b5'],[1,'#b8b5a8']]);ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
 // soft workshop window and tiled floor
 ctx.fillStyle='#cec9b9';ctx.fillRect(0,H*.59,W,H*.41);
 const wx=W*.08,wy=H*.12,ww=W*.24,wh=H*.34;rounded(wx,wy,ww,wh,4,'#bbc7bc','#9da99d');ctx.fillStyle='#dce2d5';ctx.fillRect(wx+4,wy+4,ww-8,wh-8);ctx.fillStyle='#aac0b2';ctx.fillRect(wx+7,wy+7,(ww-14)*.48,wh-14);ctx.fillStyle='#b8cdbf';ctx.fillRect(wx+ww*.53,wy+7,ww*.43,wh-14);line([wx+ww/2,wy+5],[wx+ww/2,wy+wh-5],'#87998d',3);line([wx+5,wy+wh*.52],[wx+ww-5,wy+wh*.52],'#87998d',3);
 // wall shelf, bottles, pegboard
 const sx=W*.62,sy=H*.16;rounded(sx,sy,W*.28,H*.19,5,'#c7c1af','#aaa593');for(let i=0;i<5;i++){circle(sx+W*(.035+i*.047),sy+H*.065,Math.max(3,scale*5),['#cc8258','#769182','#dfbb65','#8a9e85','#b87562'][i]);ctx.fillStyle='#6b7567';ctx.fillRect(sx+W*(.024+i*.047),sy+H*.12,W*.024,H*.045)}
 // floor tiles/perspective
 ctx.strokeStyle='#b0ad9f';ctx.lineWidth=1;for(let i=0;i<8;i++){const y=H*.62+i*i*H*.006;line([0,y],[W,y],'#b4b1a3',1)}for(let i=-5;i<10;i++){line([W*.5+(i*W*.11),H*.59],[W*.5+i*W*.23,H],'#b4b1a3',1)}
 // workbench at far right
 const bx=W*.76,by=H*.48;ctx.fillStyle='#827f70';ctx.fillRect(bx,by,W*.22,H*.045);ctx.fillStyle='#a69d88';ctx.fillRect(bx+W*.01,by-H*.03,W*.2,H*.03);ctx.fillStyle='#655f53';ctx.fillRect(bx+W*.025,by+H*.045,W*.018,H*.2);ctx.fillRect(bx+W*.19,by+H*.045,W*.018,H*.2);
 const r=Math.min(W*.185,H*.305),y=H*.685,x1=W*.25,x2=W*.75,hubY=y-r*.11;const rear=[x1,hubY],front=[x2,hubY];
 // bike stand and floor shadow
 ctx.fillStyle='#74796f';ctx.beginPath();ctx.ellipse(W*.5,H*.83,W*.26,H*.035,0,0,Math.PI*2);ctx.fill();line([W*.5,H*.76],[W*.5,H*.89],'#3d4741',Math.max(3,scale*6));line([W*.43,H*.89],[W*.57,H*.89],'#39433d',Math.max(3,scale*6));line([W*.5,H*.78],[W*.47,H*.72],'#546159',Math.max(2,scale*4));
 // wheel drawing incl depth and spokes
 function wheel(cx,cy,rad,rearWheel){const depth=Math.max(5,rad*.14);ctx.beginPath();ctx.ellipse(cx+depth,cy+depth*.4,rad,rad*.98,0,0,Math.PI*2);ctx.strokeStyle='#566058';ctx.lineWidth=Math.max(8,rad*.085);ctx.stroke();ctx.beginPath();ctx.arc(cx,cy,rad,0,Math.PI*2);ctx.strokeStyle=COLORS.rubber;ctx.lineWidth=Math.max(9,rad*.105);ctx.stroke();ctx.beginPath();ctx.arc(cx,cy,rad*.91,0,Math.PI*2);ctx.strokeStyle='#6b7066';ctx.lineWidth=Math.max(1.5,rad*.018);ctx.stroke();ctx.beginPath();ctx.arc(cx,cy,rad*.865,0,Math.PI*2);ctx.strokeStyle=COLORS.rim;ctx.lineWidth=Math.max(2,rad*.025);ctx.stroke();for(let i=0;i<20;i++){const a=i*Math.PI/10;line([cx+Math.cos(a)*rad*.1,cy+Math.sin(a)*rad*.1],[cx+Math.cos(a)*rad*.85,cy+Math.sin(a)*rad*.85],i%2?'#9ca194':'#e0ddce',Math.max(.7,rad*.007))}circle(cx,cy,rad*.09,'#858c7f','#e1dfd4',Math.max(1,rad*.013));if(rearWheel){circle(cx,cy,rad*.22,'#647066','#ccc9bb',Math.max(1,rad*.016));circle(cx,cy,rad*.17,'#aba994','#535e54',1);for(let i=0;i<16;i++){const a=i*Math.PI/8;line([cx+Math.cos(a)*rad*.09,cy+Math.sin(a)*rad*.09],[cx+Math.cos(a)*rad*.21,cy+Math.sin(a)*rad*.21],'#777f73',Math.max(.8,rad*.009))}}}
 wheel(...rear,r,true);wheel(...front,r,false);
 // bicycle tubing in faux 3D, triangle landmarks
 const crank=[W*.485,y-r*.12],seat=[W*.405,y-r*.83],head=[W*.625,y-r*.75],rearTop=[W*.31,y-r*.74],frontLow=[W*.655,y-r*.05];
 // rear stays and frame tube shadows
 const tubes=[[rear,crank],[rear,seat],[seat,crank],[seat,head],[head,crank],[head,frontLow],[frontLow,front],[head,[W*.665,y-r*.82]],[seat,[W*.365,y-r*.88]]];
 tubes.forEach((t,i)=>{line(t[0],t[1],'#583a30',Math.max(8,r*.09));line([t[0][0]-2,t[0][1]-2],[t[1][0]-2,t[1][1]-2],i===6?'#dc7a4e':COLORS.frame,Math.max(5,r*.062));line([t[0][0]-3,t[0][1]-4],[t[1][0]-3,t[1][1]-4],COLORS.frameHi,Math.max(1,r*.012))});
 // headset + fork, handlebar, seatpost/saddle
 line(head,frontLow,'#545d55',Math.max(12,r*.12));line([head[0]-3,head[1]+3],[frontLow[0]-3,frontLow[1]],'#858b7e',Math.max(5,r*.045));line([head[0],head[1]],[W*.665,y-r*.91],'#424d46',Math.max(7,r*.07));line([W*.665,y-r*.91],[W*.72,y-r*.94],'#343c37',Math.max(6,r*.055));line([W*.72,y-r*.94],[W*.755,y-r*.91],'#343c37',Math.max(6,r*.055));line(seat,[W*.365,y-r*.88],'#414a43',Math.max(7,r*.065));line([W*.34,y-r*.91],[W*.405,y-r*.89],'#302f2a',Math.max(10,r*.1));line([W*.34,y-r*.91],[W*.405,y-r*.89],'#62645a',Math.max(5,r*.045));
 // drivetrain / cranks / chain
 const crankR=r*.2;ctx.beginPath();ctx.ellipse(crank[0],crank[1],crankR,crankR*.88,0,0,Math.PI*2);ctx.strokeStyle='#515b53';ctx.lineWidth=Math.max(2,r*.025);ctx.stroke();const c1=[crank[0],crank[1]-crankR*.76],c2=[crank[0],crank[1]+crankR*.76];const chainY=hubY;line([rear[0],chainY-r*.12],[crank[0],crank[1]-crankR*.42],'#333a35',Math.max(2,r*.018));line([rear[0],chainY+r*.12],[crank[0],crank[1]+crankR*.42],'#333a35',Math.max(2,r*.018));line(crank,c1,'#a8a994',Math.max(2,r*.02));line(crank,c2,'#a8a994',Math.max(2,r*.02));line([c1[0],c1[1]],[c1[0]+r*.25,c1[1]+r*.03],'#333a35',Math.max(3,r*.04));line([c2[0],c2[1]],[c2[0]-r*.25,c2[1]-r*.03],'#333a35',Math.max(3,r*.04));
 // front/rear brake arms and cable
 for(const [cx,cy] of [[rear[0],rear[1]],[front[0],front[1]]]){line([cx-r*.16,cy-r*.84],[cx+r*.16,cy-r*.84],'#505b53',Math.max(3,r*.045));line([cx-r*.12,cy-r*.84],[cx-r*.08,cy-r*.67],'#535c54',Math.max(3,r*.04));line([cx+r*.12,cy-r*.84],[cx+r*.08,cy-r*.67],'#535c54',Math.max(3,r*.04));}
 // details / highlight accents
 ctx.strokeStyle='#f6d2ae';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(seat[0]+4,seat[1]+6);ctx.lineTo(head[0]-4,head[1]+6);ctx.stroke();circle(crank[0],crank[1],r*.045,'#c5c6b7','#3e4942',2);
 if(repairState.tire){ctx.beginPath();ctx.arc(rear[0],rear[1],r*.94,-.35,.35);ctx.strokeStyle='#c7f36b';ctx.lineWidth=3;ctx.stroke()}
 if(repairState.brake){circle(rear[0],rear[1]-r*.84,r*.055,'#c7f36b');}
 if(repairState.chain){line([rear[0],chainY-r*.12],[crank[0],crank[1]-crankR*.42],'#b9d674',Math.max(2,r*.018));line([rear[0],chainY+r*.12],[crank[0],crank[1]+crankR*.42],'#b9d674',Math.max(2,r*.018))}
 if(repairState.gears){circle(rear[0],rear[1],r*.22,'#c7f36b');}
 // wheel appears removed during tire work, parked beside bike
 if(repairState.wheel&&!repairState.tire){ctx.globalAlpha=.95;wheel(W*.14,H*.82,r*.32,false);ctx.globalAlpha=1}
 // task hotspot positions, regenerate every frame
 hotspots=[{id:'rear hub',x:rear[0],y:rear[1],r:Math.max(22,r*.21)},{id:'rear tire',x:rear[0]-r*.52,y:rear[1]-r*.5,r:Math.max(24,r*.23)},{id:'rear wheel',x:rear[0],y:rear[1],r:Math.max(25,r*.28)},{id:'rear valve',x:rear[0]+r*.67,y:rear[1]-r*.67,r:Math.max(20,r*.16)},{id:'rear brake',x:rear[0],y:rear[1]-r*.84,r:Math.max(22,r*.18)},{id:'chain',x:(rear[0]+crank[0])*.5,y:(rear[1]+crank[1])*.5,r:Math.max(22,r*.2)},{id:'rear derailleur',x:rear[0]+r*.19,y:rear[1]+r*.2,r:Math.max(22,r*.19)}];
 // subtle target halo
 if(selectedTool){const expected=expectedTarget();const hs=hotspots.find(h=>h.id===expected);if(hs){ctx.beginPath();ctx.arc(hs.x,hs.y,hs.r,0,Math.PI*2);ctx.fillStyle='#c7f36b22';ctx.fill();ctx.setLineDash([5,4]);ctx.strokeStyle='#748e4d';ctx.lineWidth=2;ctx.stroke();ctx.setLineDash([])}}
}

