const stepsEl=document.getElementById('steps'),toolsEl=document.getElementById('tools'),statusEl=document.getElementById('status');let started=false,stageIndex=0,muted=false;
function task(){return tasks[currentStep]}
function stage(){return task()?.steps[stageIndex]}
function expectedTarget(){return stage()?.[1]}
function updateUI(){stepsEl.innerHTML=tasks.map((t,i)=>`<div class="step ${i===currentStep?'active ':''}${i<currentStep?'done':''}"><span class="step-num">${i<currentStep?'✓':i+1}</span><span class="step-copy"><strong>${t.short}</strong><small>${i<currentStep?'Done':'Workshop task'}</small></span></div>`).join('');document.getElementById('progressText').textContent=`${currentStep} / ${tasks.length}`;document.getElementById('progressBar').style.width=`${currentStep/tasks.length*100}%`;
 const t=task(),s=stage();if(t){document.getElementById('taskEyebrow').textContent=`UP NEXT · STEP ${currentStep+1}`;document.getElementById('taskTitle').textContent=t.title;document.getElementById('taskDescription').textContent=t.desc;document.getElementById('taskInstruction').textContent=started?`Use the ${s[0].toLowerCase()} on the ${s[1]}.`:t.instruction;document.getElementById('targetText').textContent=`Target: ${s[1]}`;document.getElementById('targetIcon').textContent=t.icon;document.getElementById('orderText').textContent=t.order;document.getElementById('tipText').textContent=t.tip;document.getElementById('sceneBadge').textContent=started?'IN THE WORKSHOP':currentStep?'TUNE-UP IN PROGRESS':'NEEDS SOME LOVE';document.getElementById('sceneHint').innerHTML=started?`Select <b>${s[0]}</b> and tap <b>${s[1]}</b>`:'Choose a tool, then tap the matching bike part';document.getElementById('actionBtn').innerHTML=started?`Find ${s[1]} <span>→</span>`:'Inspect bike <span>→</span>';document.getElementById('actionBtn').disabled=false;}
 else{document.getElementById('progressText').textContent=`${tasks.length} / ${tasks.length}`;document.getElementById('progressBar').style.width='100%';document.getElementById('sceneBadge').textContent='ROAD READY';document.getElementById('sceneHint').textContent='Nice work, mechanic!';document.getElementById('actionBtn').disabled=true;document.getElementById('complete').classList.add('show')}
 toolsEl.innerHTML=toolDefs.map(([name,icon,key])=>`<button class="tool ${selectedTool===name?'selected':''}" data-tool="${name}" aria-label="Select ${name}"><span class="tool-icon">${icon}</span><span class="tool-name">${name}</span><span class="tool-key">${key}</span></button>`).join('');toolsEl.querySelectorAll('.tool').forEach(b=>b.onclick=()=>{selectedTool=b.dataset.tool;statusEl.textContent=`${selectedTool} selected`;statusEl.className='status';updateUI();draw();const el=toolsEl.querySelector('.selected');el?.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'})});document.getElementById('toolPrompt').textContent=started?`Now: ${s[0]}`:'The right tool makes the job easier.';draw()}
function showToast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function doAction(){if(!started){started=true;selectedTool=stage()[0];statusEl.textContent='Inspection complete. Start at the rear wheel.';statusEl.className='status good';showToast('First up: remove the rear wheel');updateUI();return}const s=stage();statusEl.textContent=`Choose ${s[0]} and tap the ${s[1]} on the bike.`;statusEl.className='status';showToast(`Target the ${s[1]}`);const target=hotspots.find(h=>h.id===s[1]);if(target){const b=scene.getBoundingClientRect();const x=target.x+ b.left,y=target.y+b.top;if(x<b.left+b.width-210&&window.innerWidth>650){}}}
document.getElementById('actionBtn').addEventListener('click',doAction);
function completeStage(){const id=stage()[2];if(id==='wheel'){repairState.wheel=true;showToast('Wheel out! Keep it safe and clean.')}if(id==='tire'){repairState.tire=true;showToast('Tire is unseated — inspect the tube.')}if(id==='tube'){repairState.tube=true;showToast('Fresh tube fitted. Check it is not twisted.')}if(id==='pump'){repairState.pumped=true;showToast('Tube inflated evenly — nearly there.')}if(id==='refit'){repairState.wheel=false;showToast('Wheel back in. Check it spins freely.')}if(id==='brake'){repairState.brake=true;showToast('Brake centered and ready to stop.')}if(id==='chain'){repairState.chain=true;showToast('Clean, quiet chain. Wipe off the extra lube.')}if(id==='gears'){repairState.gears=true;showToast('Crisp shifts! A quarter-turn can make a difference.')}
 stageIndex++;if(stageIndex>=task().steps.length){currentStep++;stageIndex=0;if(currentStep<tasks.length)showToast(`Task done! Next: ${task().title.toLowerCase()}`);else showToast('Tune-up complete! Great work.')}updateUI()}
function handleCanvasTap(e){const rect=canvas.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top;let nearest=null,dist=Infinity;for(const h of hotspots){const d=Math.hypot(x-h.x,y-h.y);if(d<h.r&&d<dist){nearest=h;dist=d}}if(!nearest){statusEl.textContent='Tap a bike part to work on it.';return}if(!started){statusEl.textContent='Tap “Inspect bike” to begin your tune-up.';return}const s=stage();if(selectedTool!==s[0]){statusEl.textContent=`That job needs the ${s[0]}. Select it below first.`;statusEl.className='status';return}if(nearest.id!==s[1]){statusEl.textContent=`Good eye, but this step needs the ${s[1]}.`;statusEl.className='status';return}statusEl.textContent=`Nice work — ${s[0].toLowerCase()} on the ${s[1]}.`;statusEl.className='status good';completeStage()}
canvas.addEventListener('pointerup',handleCanvasTap);canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;canvas.style.cursor=hotspots.some(h=>Math.hypot(x-h.x,y-h.y)<h.r)?'pointer':'default'});
document.getElementById('againBtn').addEventListener('click',()=>{currentStep=0;stageIndex=0;started=false;selectedTool=null;repairState={wheel:false,tire:false,tube:false,pumped:false,brake:false,chain:false,gears:false};document.getElementById('complete').classList.remove('show');statusEl.textContent='';updateUI()});document.getElementById('soundBtn').addEventListener('click',e=>{muted=!muted;e.currentTarget.textContent=muted?'×':'♪';showToast(muted?'Sound off':'Sound on')});window.addEventListener('resize',resize);new ResizeObserver(resize).observe(scene);resize();updateUI();
</script></body></html>

