### Ran Playwright code
```js
await (async page => {
  const desktop = await page.evaluate(() => ({
    size: [innerWidth, innerHeight],
    scene: document.querySelector('#scene').getBoundingClientRect().toJSON(),
    canvas: [document.querySelector('canvas').width, document.querySelector('canvas').height],
    stages: tasks.map(t => t.steps.length),
    jsReady: typeof updateUI === 'function'
  }));
  await page.evaluate(() => document.querySelector('#actionBtn').click());
  const outcomes = [];
  for (let i = 0; i < 11; i++) {
    const state = await page.evaluate(() => ({step: currentStep, stage: stageIndex, expected: stage()?.[1], tool: stage()?.[0], done: currentStep >= tasks.length}));
    if (state.done) break;
    await page.evaluate(tool => {
      const button = [...document.querySelectorAll('.tool')].find(el => el.dataset.tool === tool);
      if (button) button.click();
    }, state.tool);
    const point = await page.evaluate(target => {
      const h = hotspots.find(x => x.id === target);
      return h && {x: h.x, y: h.y};
    }, state.expected);
    if (!point) throw new Error(`Missing hotspot: ${state.expected}`);
    await page.locator('canvas').click({position: point});
    outcomes.push(await page.evaluate(() => ({step: currentStep, stage: stageIndex, status: document.querySelector('#status').textContent})));
  }
  const completed = await page.evaluate(() => ({step: currentStep, complete: document.querySelector('#complete').classList.contains('show'), progress: document.querySelector('#progressText').textContent}));
  await page.locator('#againBtn').click();
  const replay = await page.evaluate(() => ({step: currentStep, stage: stageIndex, complete: document.querySelector('#complete').classList.contains('show'), tool: selectedTool}));
  await page.setViewportSize({width: 390, height: 844});
  await page.waitForTimeout(300);
  const mobile = await page.evaluate(() => ({
    size:[innerWidth,innerHeight], body:[document.body.scrollWidth, document.body.scrollHeight],
    app:document.querySelector('.app').getBoundingClientRect().toJSON(),
    scene:document.querySelector('#scene').getBoundingClientRect().toJSON(),
    toolbar:document.querySelector('.toolbar').getBoundingClientRect().toJSON(),
    buttons:[...document.querySelectorAll('.tool')].map(b=>b.getBoundingClientRect().toJSON())
  }));
  console.log(JSON.stringify({desktop, outcomes, completed, replay, mobile}, null, 2));
}
)(page);
```

